"""List the alternatives generated by NSGA-III and shortlisted by SustMine's hierarchy.
Pools the 30 NSGA-III final populations at one budget, keeps the feasible nondominated
subset, applies the hierarchical ranking, and prints every design with its decision
variables, objective values, per-dimension ranks and composite rank.
Usage: python list_front1.py --in results/exp1_mip_5000 [--seed 0]"""
import argparse, glob, numpy as np, pandas as pd
from sustmine_search.ranking import pareto_rank, sustmine_rank

ap = argparse.ArgumentParser()
ap.add_argument("--in", dest="IN", default="results/exp1_mip_5000")
ap.add_argument("--seed", type=int, default=None, help="one seed instead of pooling all 30")
ap.add_argument("--front", type=int, default=1, help="print fronts up to this one")
a = ap.parse_args()

files = [f"{a.IN}/nsga3_seed{a.seed}.npz"] if a.seed is not None else sorted(glob.glob(f"{a.IN}/nsga3_seed*.npz"))
X, F = [], []
for f in files:
    d = np.load(f); feas = (d["G"] <= 0).all(axis=1)
    X.append(d["X"][feas]); F.append(d["F"][feas])
X, F = np.vstack(X), np.vstack(F)

nd = pareto_rank(F) == 1                     # nondominated subset of the pooled set
X, F = X[nd], F[nd]
XF = np.unique(np.hstack([X, F]), axis=0); X, F = XF[:, :4], XF[:, 4:]
eco, env, soc, hier = sustmine_rank(F, max_cols=[], eco_cols=[0], env_cols=[1, 2], soc_cols=[3, 4], gvf_thresh=0.80)

T = pd.DataFrame({
    "capex_$M": X[:, 0], "rate_Mt/y": X[:, 1], "thr_Mt/y": X[:, 2], "pushback": np.round(X[:, 3]).astype(int),
    "NPV_$M": -F[:, 0], "waste_Mt": F[:, 1], "land_ha.yr": F[:, 2], "employees": -F[:, 3], "life_yr": -F[:, 4],
    "rank_eco": eco, "rank_env": env, "rank_soc": soc, "front": hier})
T = T.sort_values(["front", "NPV_$M"], ascending=[True, False]).reset_index(drop=True)
T.index += 1

pd.set_option("display.width", 200); pd.set_option("display.max_rows", 500)
print(f"{len(files)} run(s), {len(F)} nondominated designs, {hier.max()} hierarchical fronts; "
      f"Front 1 = {(hier == 1).sum()}")
print(T[T.front <= a.front].round(1).to_string())
T.to_csv(f"{a.IN}/nsga3_sustmine_front1.csv", index_label="id")